go 1.26.0

require golang.org/x/sys v0.48.0
```

### 2.2 `extract.go`

```go
// Package securetar implements a hardened tar extractor whose core invariant is:
//
//	no filesystem mutation ever lands outside the extraction root.
//
// Every path is resolved by the kernel relative to an open root directory file
// descriptor with openat2(2) using RESOLVE_BENEATH, so symlinks that leave the
// root, ".." traversal, absolute names and TOCTOU symlink swaps are rejected by
// the kernel itself. Final components are additionally opened with O_NOFOLLOW so
// a member can never be written *through* a symlink. Hard links are created from
// an O_PATH fd of the already-resolved target (linkat + AT_EMPTY_PATH), which is
// immune to a later rename of the target.
//
// The package deliberately refuses hostile members with a typed *ExtractError
// naming the offending member instead of silently sanitizing it.
package securetar

import (
	"archive/tar"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"strings"
	"time"

	"golang.org/x/sys/unix"
)

// ExtractError is returned whenever a member is refused. It always names the
// archive member that triggered the failure.
type ExtractError struct {
	Op     string // operation: "validate", "open", "mkdir", "symlink", "hardlink", ...
	Member string // offending archive member name
	Reason string // human readable reason
	Escape bool   // true when the member escaped (or tried to escape) the root
	Err    error  // underlying error, if any
}

func (e *ExtractError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("securetar: %s %q: %s: %v", e.Op, e.Member, e.Reason, e.Err)
	}
	return fmt.Sprintf("securetar: %s %q: %s", e.Op, e.Member, e.Reason)
}

func (e *ExtractError) Unwrap() error { return e.Err }

// IsEscape reports whether err is an ExtractError caused by an attempt to
// leave the extraction root, either by our validation or by the kernel's
// RESOLVE_BENEATH enforcement (EXDEV).
func IsEscape(err error) bool {
	var ee *ExtractError
	if errors.As(err, &ee) && ee.Escape {
		return true
	}
	return errors.Is(err, unix.EXDEV)
}

func escapeFrom(err error) bool {
	return errors.Is(err, unix.EXDEV) || errors.Is(err, unix.ELOOP)
}

// Root is a race-free handle to an extraction root directory.
type Root struct {
	fd   int
	name string
}

// OpenRoot opens dir as an extraction root. dir should be a dedicated, private
// directory. The returned Root must be closed when done.
func OpenRoot(dir string) (*Root, error) {
	fd, err := unix.Open(dir, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, fmt.Errorf("securetar: open root %q: %w", dir, err)
	}
	return &Root{fd: fd, name: dir}, nil
}

func (r *Root) Close() error { return unix.Close(r.fd) }

// openBeneath resolves rel relative to the root (or to dirfd) with
// RESOLVE_BENEATH. Any component that would escape the starting directory
// (absolute symlink, "..", magic link) is rejected by the kernel with EXDEV or
// ELOOP.
func openBeneathAt(dirfd int, rel string, flags int, mode uint32) (int, error) {
	how := &unix.OpenHow{
		Flags:   uint64(flags) | unix.O_CLOEXEC,
		Mode:    uint64(mode),
		Resolve: unix.RESOLVE_BENEATH,
	}
	return unix.Openat2(dirfd, rel, how)
}

// openBeneath opens a path relative to the extraction root.
func (r *Root) openBeneath(rel string, flags int, mode uint32) (int, error) {
	return openBeneathAt(r.fd, rel, flags, mode)
}

// ensureDir opens rel, creating missing directory components one at a time.
// Existing intermediate symlinks are followed by the kernel but only if they
// stay beneath the directory that contains them.
func (r *Root) ensureDir(rel string) (int, error) {
	rel = strings.TrimSuffix(rel, "/")
	if rel == "" || rel == "." {
		return unix.Dup(r.fd)
	}
	cur, err := unix.Dup(r.fd)
	if err != nil {
		return -1, err
	}
	for _, comp := range strings.Split(rel, "/") {
		next, err := openBeneathAt(cur, comp, unix.O_RDONLY|unix.O_DIRECTORY, 0)
		if err != nil {
			if !errors.Is(err, unix.ENOENT) {
				unix.Close(cur)
				return -1, err
			}
			if merr := unix.Mkdirat(cur, comp, 0o700); merr != nil && !errors.Is(merr, unix.EEXIST) {
				unix.Close(cur)
				return -1, merr
			}
			next, err = openBeneathAt(cur, comp, unix.O_RDONLY|unix.O_DIRECTORY, 0)
			if err != nil {
				unix.Close(cur)
				return -1, err
			}
		}
		unix.Close(cur)
		cur = next
	}
	return cur, nil
}

// parentOf returns a directory fd for the parent of rel plus the final base
// name. Missing parents are created.
func (r *Root) parentOf(rel string) (int, string, error) {
	dir, base := path.Split(rel)
	dir = strings.TrimSuffix(dir, "/")
	if base == "" {
		return -1, "", &ExtractError{Op: "validate", Member: rel, Reason: "empty final path component"}
	}
	if dir == "" {
		fd, err := unix.Dup(r.fd)
		return fd, base, err
	}
	fd, err := r.ensureDir(dir)
	return fd, base, err
}

// lstatBeneath lstat()s rel without following the final component.
func (r *Root) lstatBeneath(rel string) (*unix.Stat_t, error) {
	fd, err := r.openBeneath(rel, unix.O_PATH|unix.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	defer unix.Close(fd)
	var st unix.Stat_t
	if err := unix.Fstat(fd, &st); err != nil {
		return nil, err
	}
	return &st, nil
}

// removeFinal unlinks the final component of rel (never a directory).
func (r *Root) removeFinal(rel string) error {
	parent, base, err := r.parentOf(rel)
	if err != nil {
		return err
	}
	defer unix.Close(parent)
	return unlinkAt(parent, base)
}

func unlinkAt(parent int, base string) error {
	err := unix.Unlinkat(parent, base, 0)
	if err == nil {
		return nil
	}
	if errors.Is(err, unix.EISDIR) || errors.Is(err, unix.EPERM) {
		// Try removing an empty directory, but never recurse.
		return unix.Unlinkat(parent, base, unix.AT_REMOVEDIR)
	}
	return err
}

// ---------------------------------------------------------------------------
// Path validation
// ---------------------------------------------------------------------------

// safeRel validates an archive member name. It rejects absolute names, NUL
// bytes and any ".." component instead of cleaning them away. Returns the
// cleaned relative path ("" for the root itself).
func safeRel(name string) (string, error) {
	if name == "" {
		return "", errors.New("empty member name")
	}
	if strings.IndexByte(name, 0) >= 0 {
		return "", errors.New("member name contains NUL byte")
	}
	if strings.HasPrefix(name, "/") {
		return "", errors.New("absolute member name")
	}
	comps := strings.Split(name, "/")
	out := make([]string, 0, len(comps))
	for _, c := range comps {
		switch c {
		case "", ".":
			// benign
		case "..":
			return "", errors.New(`member name contains ".." component`)
		default:
			out = append(out, c)
		}
	}
	return strings.Join(out, "/"), nil
}

// linkTargetStaysInside reports whether a symlink target, interpreted relative
// to memberDir, lexically stays inside the root. This is a policy check on top
// of the kernel's RESOLVE_BENEATH guarantee (which is the actual enforcement).
func linkTargetStaysInside(memberDir, target string) bool {
	if target == "" || strings.IndexByte(target, 0) >= 0 {
		return false
	}
	if strings.HasPrefix(target, "/") {
		return false
	}
	stack := []string{}
	if memberDir != "" && memberDir != "." {
		stack = append(stack, strings.Split(memberDir, "/")...)
	}
	for _, c := range strings.Split(target, "/") {
		switch c {
		case "", ".":
		default:
			if c == ".." {
				if len(stack) == 0 {
					return false
				}
				stack = stack[:len(stack)-1]
				continue
			}
			stack = append(stack, c)
		}
	}
	return true
}

// ---------------------------------------------------------------------------
// Extractor
// ---------------------------------------------------------------------------

// Extractor extracts a tar stream into a Root.
type Extractor struct {
	root        *Root
	pendingDirs []pendingDir
	// Chown, when true (and euid==0), restores ownership.
	Chown bool
}

type pendingDir struct {
	rel     string
	modTime time.Time
	access  time.Time
	change  time.Time
}

// NewExtractor creates an Extractor that writes into root.
func NewExtractor(root *Root) *Extractor { return &Extractor{root: root} }

// Extract extracts every member of r into root and returns the first refused
// member as a typed error.
func (x *Extractor) Extract(r io.Reader) error {
	tr := tar.NewReader(r)
	for {
		hdr, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		if err := x.extractOne(tr, hdr); err != nil {
			return err
		}
	}
	return x.applyPendingDirs()
}

func (x *Extractor) extractOne(tr *tar.Reader, hdr *tar.Header) error {
	rel, err := safeRel(hdr.Name)
	if err != nil {
		return &ExtractError{Op: "validate", Member: hdr.Name, Reason: err.Error(), Escape: true, Err: err}
	}
	if rel == "" { // "." root entry
		return nil
	}
	switch hdr.Typeflag {
	case tar.TypeDir:
		return x.extractDir(hdr, rel)
	case tar.TypeReg, tar.TypeRegA, tar.TypeGNUSparse:
		return x.extractReg(tr, hdr, rel)
	case tar.TypeSymlink:
		return x.extractSymlink(hdr, rel)
	case tar.TypeLink:
		return x.extractHardlink(hdr, rel)
	default:
		return &ExtractError{
			Op:     "extract",
			Member: hdr.Name,
			Reason: fmt.Sprintf("unsupported tar entry type %q", hdr.Typeflag),
		}
	}
}

func (x *Extractor) extractReg(tr *tar.Reader, hdr *tar.Header, rel string) error {
	if dir := path.Dir(rel); dir != "." {
		if _, err := x.root.ensureDir(dir); err != nil {
			return &ExtractError{Op: "mkdir", Member: hdr.Name, Reason: "cannot create parent directory", Err: err}
		}
	}
	flags := unix.O_WRONLY | unix.O_CREAT | unix.O_TRUNC | unix.O_NOFOLLOW
	mode := uint32(hdr.Mode) & 0o7777
	fd, err := x.root.openBeneath(rel, flags, mode)
	if errors.Is(err, unix.ELOOP) {
		// Existing symlink at the final component: unlink it, never follow it.
		if rerr := x.root.removeFinal(rel); rerr == nil {
			fd, err = x.root.openBeneath(rel, flags, mode)
		}
	}
	if err != nil {
		return &ExtractError{Op: "open", Member: hdr.Name, Reason: "cannot create regular file", Escape: escapeFrom(err), Err: err}
	}
	f := os.NewFile(uintptr(fd), hdr.Name)
	defer f.Close()

	n, err := io.Copy(f, tr)
	if err != nil {
		return &ExtractError{Op: "write", Member: hdr.Name, Reason: "write failed", Err: err}
	}
	if hdr.Size >= 0 && n != hdr.Size {
		// Sparse files are expanded to their logical size by archive/tar; a
		// short copy would mean a malformed stream.
		if hdr.Typeflag != tar.TypeGNUSparse && !hasGNUsparse(hdr) {
			return &ExtractError{Op: "write", Member: hdr.Name, Reason: "short write: stream ended early"}
		}
	}
	if err := x.setMetadata(fd, hdr); err != nil {
		return err
	}
	return nil
}

func hasGNUsparse(hdr *tar.Header) bool {
	if hdr.PAXRecords == nil {
		return false
	}
	_, ok := hdr.PAXRecords["GNU.sparse.map"]
	if ok {
		return true
	}
	_, ok = hdr.PAXRecords["GNU.sparse.major"]
	return ok
}

func (x *Extractor) extractDir(hdr *tar.Header, rel string) error {
	// If the final component already exists as a symlink (e.g. a hostile
	// symlink member followed by a directory member of the same name), replace
	// it with a real directory instead of following it.
	if st, err := x.root.lstatBeneath(rel); err == nil && st.Mode&unix.S_IFMT == unix.S_IFLNK {
		if err := x.root.removeFinal(rel); err != nil {
			return &ExtractError{Op: "mkdir", Member: hdr.Name, Reason: "cannot replace symlink with directory", Err: err}
		}
	}
	fd, err := x.root.ensureDir(rel)
	if err != nil {
		return &ExtractError{Op: "mkdir", Member: hdr.Name, Reason: "cannot create directory", Err: err}
	}
	defer unix.Close(fd)
	if err := unix.Fchmod(fd, uint32(hdr.Mode)&0o7777); err != nil && !errors.Is(err, unix.EPERM) {
		return &ExtractError{Op: "chmod", Member: hdr.Name, Reason: "chmod directory", Err: err}
	}
	if x.Chown && os.Geteuid() == 0 {
		_ = unix.Fchown(fd, hdr.Uid, hdr.Gid)
	}
	x.pendingDirs = append(x.pendingDirs, pendingDir{
		rel:     rel,
		modTime: hdr.ModTime,
		access:  hdr.AccessTime,
		change:  hdr.ChangeTime,
	})
	return nil
}

func (x *Extractor) extractSymlink(hdr *tar.Header, rel string) error {
	memberDir := path.Dir(rel)
	if !linkTargetStaysInside(memberDir, hdr.Linkname) {
		return &ExtractError{
			Op:     "symlink",
			Member: hdr.Name,
			Reason: fmt.Sprintf("symlink target %q escapes extraction root", hdr.Linkname),
			Escape: true,
		}
	}
	parent, base, err := x.root.parentOf(rel)
	if err != nil {
		return &ExtractError{Op: "symlink", Member: hdr.Name, Reason: "cannot create parent directory", Err: err}
	}
	defer unix.Close(parent)

	if err := unix.Symlinkat(hdr.Linkname, parent, base); err != nil {
		if errors.Is(err, unix.EEXIST) {
			if rerr := unlinkAt(parent, base); rerr == nil {
				err = unix.Symlinkat(hdr.Linkname, parent, base)
			}
		}
		if err != nil {
			return &ExtractError{Op: "symlink", Member: hdr.Name, Reason: "symlinkat failed", Err: err}
		}
	}
	return nil
}

func (x *Extractor) extractHardlink(hdr *tar.Header, rel string) error {
	target, err := safeRel(hdr.Linkname)
	if err != nil || target == "" {
		return &ExtractError{
			Op:     "hardlink",
			Member: hdr.Name,
			Reason: fmt.Sprintf("hardlink target %q escapes extraction root", hdr.Linkname),
			Escape: true,
			Err:    err,
		}
	}

	// Resolve the target atomically beneath the root and require a regular
	// file. O_NOFOLLOW means a symlink target is refused rather than linked to.
	tfd, err := x.root.openBeneath(target, unix.O_PATH|unix.O_NOFOLLOW, 0)
	if err != nil {
		return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: fmt.Sprintf("hardlink target %q not accessible", hdr.Linkname), Escape: escapeFrom(err), Err: err}
	}
	defer unix.Close(tfd)
	var st unix.Stat_t
	if err := unix.Fstat(tfd, &st); err != nil {
		return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: "cannot stat hardlink target", Err: err}
	}
	if st.Mode&unix.S_IFMT != unix.S_IFREG {
		return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: fmt.Sprintf("hardlink target %q is not a regular file", hdr.Linkname)}
	}

	dparent, dbase, err := x.root.parentOf(rel)
	if err != nil {
		return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: "cannot create parent directory", Err: err}
	}
	defer unix.Close(dparent)
	if err := unlinkAt(dparent, dbase); err != nil && !errors.Is(err, unix.ENOENT) {
		return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: "cannot replace existing destination", Err: err}
	}

	// linkat from the already-resolved target fd. AT_EMPTY_PATH makes the
	// operation immune to the target path being swapped after validation.
	if err := unix.Linkat(tfd, "", dparent, dbase, unix.AT_EMPTY_PATH); err != nil {
		// Fall back for kernels/containers that disallow AT_EMPTY_PATH.
		tparent, tbase, perr := x.root.parentOf(target)
		if perr != nil {
			return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: "cannot resolve hardlink target parent", Err: perr}
		}
		defer unix.Close(tparent)
		if lerr := unix.Linkat(tparent, tbase, dparent, dbase, 0); lerr != nil {
			return &ExtractError{Op: "hardlink", Member: hdr.Name, Reason: "linkat failed", Err: lerr}
		}
	}
	return nil
}

func (x *Extractor) setMetadata(fd int, hdr *tar.Header) error {
	if hdr.Typeflag != tar.TypeSymlink && x.Chown && os.Geteuid() == 0 {
		_ = unix.Fchown(fd, hdr.Uid, hdr.Gid)
	}
	if err := unix.Fchmod(fd, uint32(hdr.Mode)&0o7777); err != nil && !errors.Is(err, unix.EPERM) {
		return &ExtractError{Op: "chmod", Member: hdr.Name, Reason: "chmod failed", Err: err}
	}
	atime := hdr.AccessTime
	if atime.IsZero() {
		atime = hdr.ModTime
	}
	ts := []unix.Timespec{
		unix.NsecToTimespec(atime.UnixNano()),
		unix.NsecToTimespec(hdr.ModTime.UnixNano()),
	}
	if err := unix.UtimesNanoAt(fd, "", ts, unix.AT_EMPTY_PATH); err != nil {
		return &ExtractError{Op: "utimes", Member: hdr.Name, Reason: "utimes failed", Err: err}
	}
	return nil
}

func (x *Extractor) applyPendingDirs() error {
	// Deepest first so that writing children does not overwrite the parent's
	// restored mtime.
	for i := len(x.pendingDirs) - 1; i >= 0; i-- {
		pd := x.pendingDirs[i]
		fd, err := x.root.openBeneath(pd.rel, unix.O_RDONLY|unix.O_DIRECTORY, 0)
		if err != nil {
			return &ExtractError{Op: "utimes", Member: pd.rel, Reason: "cannot reopen directory", Err: err}
		}
		atime := pd.access
		if atime.IsZero() {
			atime = pd.modTime
		}
		ts := []unix.Timespec{
			unix.NsecToTimespec(atime.UnixNano()),
			unix.NsecToTimespec(pd.modTime.UnixNano()),
		}
		err = unix.UtimesNanoAt(fd, "", ts, unix.AT_EMPTY_PATH)
		unix.Close(fd)
		if err != nil {
			return &ExtractError{Op: "utimes", Member: pd.rel, Reason: "utimes directory failed", Err: err}
		}
	}
	return nil
}

// Extract is a convenience wrapper that opens dest, extracts r and closes it.
func Extract(r io.Reader, dest string) error {
	root, err := OpenRoot(dest)
	if err != nil {
		return err
	}
	defer root.Close()
	return NewExtractor(root).Extract(r)
}

